<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { Download, FileUp, RefreshCw } from 'lucide-vue-next'
import JournalTabs from '../components/JournalTabs.vue'
import Pager from '../components/Pager.vue'
import { api, dateTimeLabel, messageOf, notify, projectName, query, worklogPeriodLabel } from '../api'
import { builtinTemplate, exportKind, exportState, exportFormatLabel, type ExportFormat, type ExportJob, type ExportSourceKind, type ExportTemplate } from '../exports'
import type { Page } from '../types'
interface Source {id:string;version:number;project_id:string;title?:string;name?:string;number?:number;revision?:number;log_date?:string;period_type?:string;meeting_date?:string;content?:string}
const props=defineProps<{revision:number}>()
const templates=ref<ExportTemplate[]>([]),jobs=ref<ExportJob[]>([]),total=ref(0),offset=ref(0),error=ref(''),loading=ref(false),uploading=ref(false),creating=ref(false),retrying=ref(''),kind=ref<ExportSourceKind>('worklogs'),format=ref<ExportFormat>('docx'),template=ref('builtin-journal'),sources=ref<Source[]>([]),sourceTotal=ref(0),sourceOffset=ref(0),sourceLoading=ref(false),sourceError=ref(''),sourceSearch=ref(''),selected=ref<Source>(),fileInput=ref<HTMLInputElement>(),detail=ref<ExportJob>(),detailError=ref('')
const limit=15,sourceLimit=20,highlight=ref(new URLSearchParams(location.hash.split('?')[1]||'').get('job')||'')
const availableTemplates=computed(()=>templates.value.filter(t=>!t.id.startsWith('builtin-')||t.id===builtinTemplate(kind.value)))
let timer:ReturnType<typeof setInterval>|undefined,jobRequest=0,sourceRequest=0
function sourceLabel(s:Source){return s.title||(s.name?`${s.number} · ${s.name}`:'')||`${s.log_date||'日志'}${s.period_type?' '+worklogPeriodLabel(s.period_type):''} · ${s.project_id?projectName(s.project_id):'全部项目'}`}
async function loadJobs(quiet=false){const request=++jobRequest;if(!quiet)loading.value=true;try{const data=await api<Page<ExportJob>>(`/api/export-jobs?${query({limit,offset:offset.value})}`);if(request===jobRequest){jobs.value=data.items;total.value=data.total;if(detail.value){const current=data.items.find(j=>j.id===detail.value?.id);if(current)detail.value=current}}}catch(e){if(request===jobRequest)error.value=messageOf(e)}finally{if(request===jobRequest)loading.value=false}}
async function loadTemplates(){templates.value=(await api<Page<ExportTemplate>>('/api/export-templates')).items;if(!availableTemplates.value.some(t=>t.id===template.value))template.value=builtinTemplate(kind.value)}
async function loadSources(next=0){const request=++sourceRequest;sourceOffset.value=next;sourceLoading.value=true;sourceError.value='';try{const path=({project_daily_logs:'project-daily-logs',meeting_minutes:'meeting-minutes',plan_versions:'plan-versions'} as Record<string,string>)[kind.value]||kind.value;const data=await api<Page<Source>>(`/api/${path}?${query({q:sourceSearch.value,limit:sourceLimit,offset:next})}`);if(request===sourceRequest){sources.value=data.items;sourceTotal.value=data.total}}catch(e){if(request===sourceRequest)sourceError.value=messageOf(e)}finally{if(request===sourceRequest)sourceLoading.value=false}}
async function refresh(){error.value='';await Promise.all([loadJobs(),loadTemplates().catch(e=>{error.value=messageOf(e)})])}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;if(!file.name.toLowerCase().endsWith('.docx')){error.value='请选择 .docx 模板';input.value='';return}uploading.value=true;error.value='';try{const body=new FormData();body.append('file',file);body.append('name',file.name.replace(/\.docx$/i,''));const saved=await api<ExportTemplate>('/api/export-templates',{method:'POST',body});await loadTemplates();template.value=saved.id;notify('Word 模板已上传，可用于新导出任务')}catch(e){error.value=messageOf(e)}finally{uploading.value=false;input.value=''}}
async function create(){if(!selected.value||creating.value)return;creating.value=true;error.value='';try{const job=await api<ExportJob>('/api/export-jobs',{method:'POST',body:JSON.stringify({source_kind:kind.value,source_id:selected.value.id,source_version:selected.value.version,...(format.value==='docx'?{template_id:template.value||builtinTemplate(kind.value)}:{}),format:format.value})});highlight.value=job.id;offset.value=0;await loadJobs();notify('导出任务已创建')}catch(e){error.value=messageOf(e)}finally{creating.value=false}}
async function retry(job:ExportJob){if(retrying.value)return;retrying.value=job.id;error.value='';try{const fresh=await api<ExportJob>('/api/export-jobs',{method:'POST',body:JSON.stringify({source_kind:job.source_kind,source_id:job.source_id,source_version:job.source_version,template_id:job.template_id,template_hash:job.template_hash,format:job.format})});highlight.value=fresh.id;offset.value=0;await loadJobs();notify('已创建新的重试任务，原失败记录保留')}catch(e){error.value=messageOf(e)}finally{retrying.value=''}}
async function showDetail(id:string){detailError.value='';try{detail.value=await api<ExportJob>(`/api/export-jobs/${encodeURIComponent(id)}`)}catch(e){detailError.value=messageOf(e)}}
async function page(next:number){offset.value=next;await loadJobs()}
watch(kind,()=>{selected.value=undefined;sourceSearch.value='';template.value=builtinTemplate(kind.value);void loadSources()})
watch(()=>props.revision,()=>{void loadSources();void loadJobs()})
onMounted(()=>{void refresh();void loadSources();if(highlight.value)void showDetail(highlight.value);timer=setInterval(()=>{if(jobs.value.some(j=>['queued','running'].includes(j.state))||detail.value&&['queued','running'].includes(detail.value.state)){void loadJobs(true);if(detail.value)void showDetail(detail.value.id)}},2500)})
onUnmounted(()=>{clearInterval(timer);jobRequest++;sourceRequest++})
defineExpose({canLeave:()=>!creating.value&&!uploading.value})
</script>
<template>
<div class="page-heading"><div><h1>工作日志</h1><p class="page-description">选择已保存版本和模板，生成可下载、可核对的文档。</p></div></div><JournalTabs active="exports"/>
<div v-if="error" class="error-banner" role="alert">{{error}}<button type="button" class="text-button" @click="refresh">刷新</button></div>
<div class="export-layout"><section class="surface export-create"><div class="section-heading"><h2>新建导出</h2></div><div class="export-body">
<div class="form-row"><label>内容类型<select v-model="kind" :disabled="creating"><option value="worklogs">个人日志</option><option value="project_daily_logs">项目日志</option><option value="issues">问题台账</option><option value="meeting_minutes">会议纪要</option><option value="plan_versions">计划版本</option><option value="requirements">需求</option></select></label><label>文件格式<select v-model="format" :disabled="creating"><option value="docx">Word（.docx）</option><option value="md">Markdown（.md）</option><option value="json">JSON（.json）</option><option value="xlsx">Excel（.xlsx）</option><option value="html">打印稿（打印 / 保存 PDF）</option></select></label></div>
<label>查找已保存内容<div class="export-source-search"><input v-model="sourceSearch" placeholder="按正文或标题搜索" @keydown.enter.prevent="loadSources()"/><button type="button" class="button subtle small" :disabled="sourceLoading" @click="loadSources()">查询</button></div></label>
<p v-if="sourceError" class="form-error" role="alert">{{sourceError}}</p><p v-else-if="sourceLoading" class="loading-message">正在读取已保存内容…</p><div v-else-if="sources.length" class="export-source-list" role="group" aria-label="选择导出内容"><label v-for="source in sources" :key="source.id"><input type="radio" name="export-source" :checked="selected?.id===source.id" @change="selected=source"/><span>{{sourceLabel(source)}}<small>数据版本 {{source.version}}<template v-if="source.revision"> · 需求修订 {{source.revision}}</template></small></span></label></div><p v-else class="input-hint">没有符合条件的已保存内容。先保存对应内容，再创建导出。</p>
<Pager :offset="sourceOffset" :limit="sourceLimit" :total="sourceTotal" @change="loadSources"/><p v-if="selected" class="input-hint export-selection">已选择：{{sourceLabel(selected)}} · 版本 {{selected.version}}</p>
<label>Word 模板<select v-model="template" :disabled="creating||format!=='docx'"><option v-for="item in availableTemplates" :key="item.id" :value="item.id">{{item.name}}</option></select></label><p v-if="format!=='docx'" class="input-hint">所选格式使用固定报告布局，保留已保存版本的内容。打印稿可在浏览器打印或保存为 PDF。</p><button type="button" class="button primary" :disabled="creating||!selected||(format==='docx'&&!template)" @click="create">{{creating?'正在创建…':'创建导出任务'}}</button>
</div></section><section class="surface export-templates"><div class="section-heading"><h2>Word 模板 <span class="count">{{templates.length}}</span></h2><button type="button" class="button subtle small" :disabled="uploading" @click="fileInput?.click()"><FileUp :size="15"/>{{uploading?'上传中…':'上传 .docx'}}</button><input ref="fileInput" class="sr-only" type="file" accept=".docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document" aria-label="上传 Word 模板" @change="upload"/></div><div class="export-body">
<p class="input-hint">在 Word 中填写占位符，再上传模板。支持字段由下列模板说明列出；正文使用 <code v-pre>{{content}}</code>。</p><p class="input-hint" v-pre>基础字段：{{title}}、{{content}}、{{project_name}}、{{date}}。</p>
<div v-for="item in templates" :key="item.id" class="export-template"><div><strong>{{item.name}}</strong><a class="text-button" :href="`/api/export-templates/${encodeURIComponent(item.id)}/download`" download><Download :size="14"/>下载模板</a></div><p>{{item.description}}</p><p class="template-fields">支持字段：{{item.fields?.join('、')||'请下载模板查看'}}</p><details><summary>模板 SHA256</summary><code>{{item.sha256||'未提供'}}</code></details></div>
</div></section></div>
<section class="surface export-jobs"><div class="section-heading"><h2>导出任务 <span class="count">{{total}}</span></h2><button type="button" class="button subtle small" :disabled="loading" @click="refresh"><RefreshCw :size="15"/>刷新状态</button></div><p v-if="loading&&!jobs.length" class="loading-message">正在读取导出任务…</p><p v-else-if="!jobs.length" class="empty-state compact">还没有导出任务。可在日志或问题详情点击“导出 Word”，也可在上方新建。</p>
<div v-else class="table-scroll"><table><thead><tr><th>来源 / 版本</th><th>格式 / 模板</th><th>状态 / 创建时间</th><th>产物 / 校验信息</th><th class="right">操作</th></tr></thead><tbody><tr v-for="job in jobs" :key="job.id" :class="{'export-highlight':highlight===job.id}"><td><button type="button" class="table-title" @click="showDetail(job.id)">{{exportKind(job.source_kind)}} · 版本 {{job.source_version}}</button><small>{{job.source_id}}</small></td><td>{{exportFormatLabel(job.format)}}<small>{{job.format==='docx'?(templates.find(t=>t.id===job.template_id)?.name||job.template_id):job.format==='xlsx'?'固定 Excel 报表':job.format==='html'?'固定打印布局':'固定导出格式'}}</small><details><summary>模板哈希</summary><code>{{job.template_hash}}</code></details></td><td><span class="badge" :class="{done:job.state==='succeeded',doing:['running','queued'].includes(job.state),abnormal:job.state==='failed'}">{{exportState(job.state)}}</span><small>{{dateTimeLabel(job.created_at)}}</small><p v-if="job.error" class="export-job-error" role="alert">{{job.error}}</p></td><td><template v-if="job.state==='succeeded'">{{job.output_name}}<small>{{job.size}} B</small><details><summary>产物 SHA256</summary><code>{{job.output_sha256}}</code></details></template><span v-else class="muted">{{job.state==='failed'?'生成失败，可新建重试任务':'生成完成后可下载'}}</span></td><td class="right"><a v-if="job.state==='succeeded'&&job.format==='html'" class="button subtle small" :href="`/api/export-jobs/${encodeURIComponent(job.id)}/print`" target="_blank" rel="noopener">打开打印稿</a><a v-if="job.state==='succeeded'" class="button subtle small" :href="`/api/export-jobs/${encodeURIComponent(job.id)}/download`" :download="job.output_name"><Download :size="14"/>下载</a><button v-if="job.state==='failed'" type="button" class="button subtle small" :disabled="!!retrying" @click="retry(job)">{{retrying===job.id?'正在创建…':'新建重试'}}</button><button type="button" class="text-button export-detail-button" @click="showDetail(job.id)">详情</button></td></tr></tbody></table></div><Pager :offset="offset" :limit="limit" :total="total" @change="page"/></section>
<p v-if="detailError" class="form-error" role="alert">{{detailError}}</p><section v-if="detail" class="surface export-detail"><div class="section-heading"><h2>任务详情 · {{exportState(detail.state)}}</h2><button type="button" class="text-button" @click="detail=undefined">收起</button></div><dl><dt>任务 ID</dt><dd>{{detail.id}}</dd><dt>来源</dt><dd>{{exportKind(detail.source_kind)}} / {{detail.source_id}} / 版本 {{detail.source_version}}</dd><dt>模板</dt><dd>{{detail.template_id}}<code>{{detail.template_hash}}</code></dd><dt>产物</dt><dd>{{detail.output_name||'尚未生成'}}<code v-if="detail.output_sha256">{{detail.output_sha256}}</code></dd><dt>更新时间</dt><dd>{{dateTimeLabel(detail.updated_at)}}</dd><template v-if="detail.error"><dt>失败原因</dt><dd class="export-job-error">{{detail.error}}</dd></template></dl></section>
</template>
<style scoped>
.export-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px;align-items:start;margin-bottom:24px}.export-body{padding:20px 22px}.export-body>.button.primary{margin-top:14px}.export-source-search{display:flex;gap:8px;margin-top:6px}.export-source-list{max-height:240px;overflow:auto;border:1px solid var(--border);border-radius:4px}.export-source-list label{display:flex;gap:10px;margin:0;padding:11px 12px;border-bottom:1px solid var(--border);font-size:12px;cursor:pointer}.export-source-list label:last-child{border-bottom:0}.export-source-list input{width:15px;min-height:15px;flex-shrink:0;margin:4px 0 0}.export-source-list small{display:block;color:var(--muted);font-size:10px}.export-selection{margin:12px 0}.export-body>.pager{padding:12px 0;border:0}.export-template{padding:18px 0;border-bottom:1px solid var(--border)}.export-template:last-child{border:0;padding-bottom:0}.export-template>div{display:flex;align-items:center;justify-content:space-between;gap:12px}.export-template strong{font-size:13px;font-weight:500}.export-template p{font-size:12px;color:#71849d;line-height:1.8;margin-top:6px}.template-fields{overflow-wrap:anywhere}details{font-size:10px;color:#7487a1;margin-top:7px}summary{cursor:pointer}code{display:block;overflow-wrap:anywhere;max-width:65ch;font-size:10px;line-height:1.8;margin-top:6px}.input-hint code{display:inline}.export-jobs table{min-width:920px}.export-job-error{white-space:pre-wrap;overflow-wrap:anywhere;color:#a55543;font-size:11px;max-width:38ch;margin-top:8px}.export-highlight{background:#edf4ff}.export-detail-button{display:block;margin-left:auto;margin-top:8px}.export-detail{margin-top:20px}.export-detail dl{display:grid;grid-template-columns:100px minmax(0,1fr);gap:14px;padding:20px 22px;margin:0;font-size:12px}.export-detail dt{color:var(--muted)}.export-detail dd{margin:0;overflow-wrap:anywhere}.export-templates .section-heading{flex-wrap:wrap}@media(max-width:1000px){.export-layout{grid-template-columns:1fr}}@media(max-width:600px){.export-body{padding:16px}.export-detail dl{grid-template-columns:1fr;gap:8px}.export-detail dd{margin-bottom:9px}}
</style>
